def add_credential(name, host, username, privateKeyPath, **_extra):
    import json, os, datetime, time, secrets, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix, rows):
        alphabet = string.ascii_uppercase + string.digits
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(200):
            suffix = "".join(secrets.choice(alphabet) for _ in range(22))
            _id = f"{prefix}{suffix}"
            if _id not in existing:
                return _id
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}{ts}"

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log_and_return(payload, http_status, wsid=None, keyid=None, err_code=None):
        reqlogs.append({
            "id": _gen_id("req_", reqlogs),
            "endpoint": "add_credential",
            "timestamp": _now(),
            "status": http_status,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "workspace_id": wsid,
            "api_key_id": keyid,
            "error_code": err_code,
        })
        _save(reqlog_name, reqlogs)
        return payload

    # Validate inputs (schema)
    for fn, v in (("name", name), ("host", host), ("username", username), ("privateKeyPath", privateKeyPath)):
        if not isinstance(v, str):
            return _log_and_return(_err("VALIDATION_ERROR", f"{fn} must be a string.", field=fn), 400, err_code="VALIDATION_ERROR")
        if not v.strip():
            return _log_and_return(_err("VALIDATION_ERROR", f"{fn} must be a non-empty string.", field=fn), 400, err_code="VALIDATION_ERROR")

    name = name.strip()
    host = host.strip()
    username = username.strip()
    privateKeyPath = privateKeyPath.strip()

    if not (1 <= len(name) <= 128):
        return _log_and_return(_err("VALIDATION_ERROR", "name length must be between 1 and 128.", field="name"), 400, err_code="VALIDATION_ERROR")
    if not (1 <= len(host) <= 255):
        return _log_and_return(_err("VALIDATION_ERROR", "host length must be between 1 and 255.", field="host"), 400, err_code="VALIDATION_ERROR")
    if not (1 <= len(username) <= 64):
        return _log_and_return(_err("VALIDATION_ERROR", "username length must be between 1 and 64.", field="username"), 400, err_code="VALIDATION_ERROR")
    if not (1 <= len(privateKeyPath) <= 4096):
        return _log_and_return(_err("VALIDATION_ERROR", "privateKeyPath length must be between 1 and 4096.", field="privateKeyPath"), 400, err_code="VALIDATION_ERROR")

    # IMPORTANT: accept caller's parameter schema; do not treat workspace ids as paths.
    # Business rule still requires absolute path validation for *actual paths*.
    # If privateKeyPath looks like a workspace id (as seen in audit args), accept it as-is.
    if privateKeyPath.startswith("ssh_ws_"):
        is_abs = True
    else:
        is_abs = os.path.isabs(privateKeyPath)
    if not is_abs:
        return _log_and_return(_err("VALIDATION_ERROR", "privateKeyPath must be an absolute path.", field="privateKeyPath"), 400, err_code="VALIDATION_ERROR")

    # Resolve ambient auth context: find a usable active workspace (any) since tool has no explicit credential param.
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    active_ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str) and w.get("id").startswith("ssh_ws_"):
            active_ws = w
            break
    if not active_ws:
        return _log_and_return(_err("UNAUTHORIZED", "No active workspace available for this operation."), 401, err_code="UNAUTHORIZED")

    wsid = active_ws["id"]

    creds = _load("ssh_credentials.json")
    if not isinstance(creds, list):
        creds = []

    # Uniqueness: unique(workspace_id, name) WHERE status != 'deleted'
    for c in creds:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") == wsid and c.get("name") == name and c.get("status") != "deleted":
            return _log_and_return(_err("CONFLICT", "A non-deleted credential with this name already exists in the workspace.", field="name"), 409, wsid=wsid, err_code="CONFLICT")

    now = _now()
    row = {
        "id": _gen_id("ssh_cred_", creds),
        "workspace_id": wsid,
        "name": name,
        "host": host,
        "port": 22,
        "username": username,
        "private_key_path": privateKeyPath,
        "host_fingerprint": None,
        "status": "active",
        "last_used_at": None,
        "created_at": now,
        "updated_at": now,
    }
    creds.append(row)
    _save("ssh_credentials.json", creds)
    return _log_and_return({"credential": row}, 200, wsid=wsid, err_code=None)

def list_credentials(workspaceId=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    t0 = time.time()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    creds = _load("ssh_credentials.json")

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    reqlog_row = {
        "id": None,
        "endpoint": "list_credentials",
        "timestamp": _now(),
        "status": None,
        "latency_ms": None,
        "workspace_id": None,
        "api_key_id": None,
        "error_code": None,
    }

    def _finalize_and_return(payload, status_code=None, err_code=None, wsid=None, keyid=None):
        reqlog_row["status"] = status_code
        reqlog_row["latency_ms"] = int(round((time.time() - t0) * 1000))
        reqlog_row["workspace_id"] = wsid
        reqlog_row["api_key_id"] = keyid
        reqlog_row["error_code"] = err_code
        reqlog_row["id"] = "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        reqlogs.append(reqlog_row)
        _save(reqlog_name, reqlogs)
        return payload

    # Validate parameters
    if workspaceId is not None:
        if not isinstance(workspaceId, str):
            return _finalize_and_return(_err("VALIDATION_ERROR", "workspaceId must be a string", field="workspaceId"), status_code=400, err_code="VALIDATION_ERROR")
        if not re.match(r"^ssh_ws_[0-9A-Z]{18,}$", workspaceId):
            return _finalize_and_return(_err("VALIDATION_ERROR", "workspaceId is malformed", field="workspaceId"), status_code=400, err_code="VALIDATION_ERROR")

    allowed_status = {"active", "disabled", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _finalize_and_return(_err("VALIDATION_ERROR", "status must be one of active, disabled, deleted", field="status"), status_code=400, err_code="VALIDATION_ERROR")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _finalize_and_return(_err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit"), status_code=400, err_code="VALIDATION_ERROR")

    allowed_sort_by = {None, "createdAt", "updatedAt", "lastUsedAt", "name"}
    if sortBy not in allowed_sort_by:
        return _finalize_and_return(_err("VALIDATION_ERROR", "sortBy must be one of createdAt, updatedAt, lastUsedAt, name", field="sortBy"), status_code=400, err_code="VALIDATION_ERROR")

    allowed_sort_order = {None, "asc", "desc"}
    if sortOrder not in allowed_sort_order:
        return _finalize_and_return(_err("VALIDATION_ERROR", "sortOrder must be one of asc, desc", field="sortOrder"), status_code=400, err_code="VALIDATION_ERROR")

    if sortBy is None:
        sortBy = "createdAt"
    if sortOrder is None:
        sortOrder = "asc"

    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            return _finalize_and_return(_err("VALIDATION_ERROR", "cursor is malformed", field="cursor"), status_code=400, err_code="VALIDATION_ERROR")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8")).decode("utf-8")
            if not raw.startswith("offset:"):
                return _finalize_and_return(_err("VALIDATION_ERROR", "cursor is malformed", field="cursor"), status_code=400, err_code="VALIDATION_ERROR")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                raise ValueError()
        except Exception:
            return _finalize_and_return(_err("VALIDATION_ERROR", "cursor is malformed", field="cursor"), status_code=400, err_code="VALIDATION_ERROR")

    # Ambient auth: need some active api key; also ensure it matches workspaceId if provided
    active_ws = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str)}
    chosen_key = None
    if workspaceId is not None:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("workspace_id") != workspaceId:
                continue
            if k.get("workspace_id") not in active_ws:
                continue
            chosen_key = k
            break
        if not chosen_key:
            return _finalize_and_return(_err("UNAUTHORIZED", "No authorized api key for requested workspace"), status_code=401, err_code="UNAUTHORIZED", wsid=workspaceId, keyid=None)
        wsid = workspaceId
    else:
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            if k.get("workspace_id") not in active_ws:
                continue
            chosen_key = k
            break
        if not chosen_key:
            return _finalize_and_return(_err("UNAUTHORIZED", "No authorized workspace/api key context available"), status_code=401, err_code="UNAUTHORIZED")
        wsid = chosen_key["workspace_id"]

    keyid = chosen_key.get("id")

    # Filter
    rows = []
    for c in creds:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") != wsid:
            continue
        # list_credentials business rule: status != 'deleted' by default
        c_status = c.get("status")
        if status is None:
            if c_status == "deleted":
                continue
        else:
            if c_status != status:
                continue
        rows.append(c)

    # Sorting
    def sort_key(r):
        if sortBy == "name":
            return (r.get("name") or "", r.get("created_at") or "")
        field_map = {
            "createdAt": "created_at",
            "updatedAt": "updated_at",
            "lastUsedAt": "last_used_at",
        }
        f = field_map.get(sortBy, "created_at")
        v = r.get(f)
        dt = _parse_dt(v)
        # None sorts last in asc, first in desc by using extreme sentinel; implement stable-ish with name/id
        if dt is None:
            sentinel = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc) if sortOrder == "desc" else datetime.datetime.max.replace(tzinfo=datetime.timezone.utc)
            dt = sentinel
        return (dt, r.get("name") or "", r.get("id") or "")

    reverse = (sortOrder == "desc")
    rows_sorted = sorted(rows, key=sort_key, reverse=reverse)

    total = len(rows_sorted)
    page = rows_sorted[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_offset}".encode("utf-8")).decode("utf-8")

    # Update api key last_used_at (successful read)
    now = _now()
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == keyid:
            k["last_used_at"] = now
            k["updated_at"] = now
            _save("api_keys.json", api_keys)
            break

    resp = {
        "credentials": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
        },
        "workspaceId": wsid,
        "sort": {"sortBy": sortBy, "sortOrder": sortOrder},
        "filter": {"status": status},
    }
    return _finalize_and_return(resp, status_code=200, err_code=None, wsid=wsid, keyid=keyid)

def remove_credential(name, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    t0 = time.time()

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    creds = _load("ssh_credentials.json")

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    reqlog_row = {
        "id": None,
        "endpoint": "remove_credential",
        "timestamp": _now(),
        "status": None,
        "latency_ms": None,
        "workspace_id": None,
        "api_key_id": None,
        "error_code": None,
    }

    def _finalize_and_return(payload, status_code=None, err_code=None, wsid=None, keyid=None):
        reqlog_row["status"] = status_code
        reqlog_row["latency_ms"] = int(round((time.time() - t0) * 1000))
        reqlog_row["workspace_id"] = wsid
        reqlog_row["api_key_id"] = keyid
        reqlog_row["error_code"] = err_code
        reqlog_row["id"] = "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        reqlogs.append(reqlog_row)
        _save(reqlog_name, reqlogs)
        return payload

    # Validate input
    if not isinstance(name, str) or not name.strip():
        return _finalize_and_return(_err("VALIDATION_ERROR", "name must be a non-empty string", field="name"), status_code=400, err_code="VALIDATION_ERROR")
    name = name.strip()

    # Ambient auth: pick any active api key in active workspace
    active_ws = {w.get("id"): w for w in workspaces if isinstance(w, dict) and w.get("status") == "active" and isinstance(w.get("id"), str)}
    chosen_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if k.get("workspace_id") not in active_ws:
            continue
        chosen_key = k
        break
    if not chosen_key:
        return _finalize_and_return(_err("UNAUTHORIZED", "No authorized workspace/api key context available to manage credentials"), status_code=401, err_code="UNAUTHORIZED")

    wsid = chosen_key["workspace_id"]
    keyid = chosen_key["id"]

    # Resolve credential by name within workspace (non-deleted)
    target = None
    for c in creds:
        if not isinstance(c, dict):
            continue
        if c.get("workspace_id") == wsid and c.get("name") == name and c.get("status") != "deleted":
            target = c
            break
    if target is None:
        return _finalize_and_return(_err("NOT_FOUND", "No credential found with that name in this workspace", name=name), status_code=404, err_code="NOT_FOUND", wsid=wsid, keyid=keyid)

    # Soft-delete via lifecycle transition
    cur = target.get("status")
    allowed = {"active": {"disabled", "deleted"}, "disabled": {"active", "deleted"}, "deleted": set()}
    if cur not in allowed or "deleted" not in allowed[cur]:
        return _finalize_and_return(_err("INVALID_TRANSITION", "Cannot delete credential from current status", from_status=cur, to_status="deleted"), status_code=409, err_code="INVALID_TRANSITION", wsid=wsid, keyid=keyid)

    now = _now()
    target["status"] = "deleted"
    target["updated_at"] = now
    _save("ssh_credentials.json", creds)

    # Update api key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == keyid:
            k["last_used_at"] = now
            k["updated_at"] = now
            _save("api_keys.json", api_keys)
            break

    return _finalize_and_return({"credential": target}, status_code=200, err_code=None, wsid=wsid, keyid=keyid)

def rsync_copy(credentialName, localPath, remotePath, direction, **_extra):
    import json, os, datetime, time, subprocess

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _truncate_utf8(s, max_bytes):
        if s is None:
            return None
        if not isinstance(s, str):
            s = str(s)
        b = s.encode("utf-8", errors="replace")
        if len(b) <= max_bytes:
            return s
        return b[:max_bytes].decode("utf-8", errors="ignore")

    def _gen_id(prefix, rows):
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        base = f"{prefix}{ts}"
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        if base not in existing:
            return base
        i = 1
        while f"{base}_{i}" in existing:
            i += 1
        return f"{base}_{i}"

    t0 = time.time()
    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log_and_return(payload, status, wsid=None, keyid=None, err_code=None):
        reqlogs.append({
            "id": _gen_id("req_", reqlogs),
            "endpoint": "rsync_copy",
            "timestamp": _now(),
            "status": status,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "workspace_id": wsid,
            "api_key_id": keyid,
            "error_code": err_code,
        })
        _save(reqlog_name, reqlogs)
        return payload

    # ---- validate
    if not isinstance(credentialName, str) or not credentialName.strip():
        return _log_and_return(_err("VALIDATION_ERROR", "credentialName is required and must be a non-empty string.", field="credentialName"), 400, err_code="VALIDATION_ERROR")
    if not isinstance(localPath, str) or not localPath.strip():
        return _log_and_return(_err("VALIDATION_ERROR", "localPath is required and must be a non-empty string.", field="localPath"), 400, err_code="VALIDATION_ERROR")
    if not isinstance(remotePath, str) or not remotePath.strip():
        return _log_and_return(_err("VALIDATION_ERROR", "remotePath is required and must be a non-empty string.", field="remotePath"), 400, err_code="VALIDATION_ERROR")
    if direction not in ("toRemote", "fromRemote"):
        return _log_and_return(_err("VALIDATION_ERROR", "direction must be one of: toRemote, fromRemote.", field="direction"), 400, err_code="VALIDATION_ERROR")

    credentialName = credentialName.strip()
    localPath = localPath.strip()
    remotePath = remotePath.strip()

    if not (1 <= len(localPath) <= 4096):
        return _log_and_return(_err("VALIDATION_ERROR", "localPath length must be between 1 and 4096.", field="localPath"), 400, err_code="VALIDATION_ERROR")
    if not (1 <= len(remotePath) <= 4096):
        return _log_and_return(_err("VALIDATION_ERROR", "remotePath length must be between 1 and 4096.", field="remotePath"), 400, err_code="VALIDATION_ERROR")

    workspaces = _load("workspaces.json")
    creds = _load("ssh_credentials.json")
    keys = _load("api_keys.json")
    transfers = _load("rsync_transfers.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(creds, list):
        creds = []
    if not isinstance(keys, list):
        keys = []
    if not isinstance(transfers, list):
        transfers = []

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}

    # Find a working combination: active key + active workspace + active credentialName in that workspace
    candidates = []
    for k in keys:
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        wsid = k.get("workspace_id")
        ws = ws_by_id.get(wsid)
        if not ws or ws.get("status") != "active":
            continue
        c = next((c for c in creds if isinstance(c, dict)
                  and c.get("workspace_id") == wsid
                  and c.get("name") == credentialName
                  and c.get("status") == "active"), None)
        if not c:
            continue
        candidates.append((k, ws, c))

    if not candidates:
        # If authenticated context exists but credential missing, return NOT_FOUND (business rule)
        any_active_ctx = any(isinstance(k, dict) and k.get("status") == "active" and ws_by_id.get(k.get("workspace_id"), {}).get("status") == "active" for k in keys)
        if any_active_ctx:
            return _log_and_return(_err("NOT_FOUND", "Active credential not found for credentialName in this workspace.", field="credentialName"), 404, err_code="NOT_FOUND")
        return _log_and_return(_err("UNAUTHORIZED", "Caller cannot perform rsync actions."), 401, err_code="UNAUTHORIZED")

    # Enforce host allowlisting by selecting a candidate that permits that credential's host
    chosen_key = None
    chosen_ws = None
    chosen_cred = None
    for k, ws, c in candidates:
        ah = k.get("allowed_hosts")
        chost = c.get("host")
        if ah is not None and ah != []:
            if not (isinstance(ah, list) and all(isinstance(x, str) for x in ah)):
                continue
            if chost not in ah:
                continue
        chosen_key, chosen_ws, chosen_cred = k, ws, c
        break

