    wsid = chosen_ws.get("id")
    keyid = chosen_key.get("id")
    cred_id = chosen_cred.get("id")
    target_host = chosen_cred.get("host")

    # Create transfer row first
    transfer_id = _gen_id("ssh_rsync_", transfers)
    row = {
        "id": transfer_id,
        "workspace_id": wsid,
        "api_key_id": keyid,
        "credential_id": cred_id,
        "direction": direction,
        "local_path": localPath,
        "remote_path": remotePath,
        "status": "queued",
        "started_at": None,
        "finished_at": None,
        "bytes_transferred": None,
        "rsync_exit_code": None,
        "output_log": None,
        "error_message": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    transfers.append(row)

    # Quota/rate limit enforcement per api key for rsync_copy
    nowdt = datetime.datetime.now(datetime.timezone.utc)
    hour_ago = nowdt - datetime.timedelta(hours=1)

    def _count_rsync_last_hour(keyid_):
        c = 0
        for tr in transfers:
            if not isinstance(tr, dict):
                continue
            if tr.get("api_key_id") != keyid_:
                continue
            created = _parse_dt(tr.get("created_at"))
            if created and created >= hour_ago:
                c += 1
        return c

    maxph = chosen_key.get("max_rsync_per_hour")
    if not isinstance(maxph, int) or maxph < 0 or maxph > 10000:
        # cannot serve this request with broken key config
        row["status"] = "failed"
        row["finished_at"] = _now()
        row["updated_at"] = _now()
        row["error_message"] = "api key is misconfigured: max_rsync_per_hour invalid"
        row["rsync_exit_code"] = 255
        _save("rsync_transfers.json", transfers)
        return _log_and_return(_err("UNAUTHORIZED", "Caller cannot perform rsync actions."), 401, wsid=wsid, keyid=keyid, err_code="UNAUTHORIZED")

    if maxph == 0 or _count_rsync_last_hour(keyid) > maxph:
        row["status"] = "failed"
        row["finished_at"] = _now()
        row["updated_at"] = _now()
        row["error_message"] = "rate limit exceeded: max_rsync_per_hour reached for this API key"
        row["rsync_exit_code"] = 255
        _save("rsync_transfers.json", transfers)
        return _log_and_return(_err("RATE_LIMIT", "rate limit exceeded: max_rsync_per_hour reached for this API key"), 429, wsid=wsid, keyid=keyid, err_code="RATE_LIMIT")

