        _save("rsync_transfers.json", transfers)
        return _log_and_return({"transfer": row}, 200, wsid=wsid, keyid=keyid, err_code=None)

    # Start running
    row["status"] = "running"
    row["started_at"] = _now()
    row["updated_at"] = _now()
    _save("rsync_transfers.json", transfers)

    # Execute rsync (best-effort). If rsync is missing, fail with useful error.
    max_log = 2 * 1024 * 1024
    ssh_cmd = f"ssh -i {pk} -o BatchMode=yes -o StrictHostKeyChecking=accept-new"

    if direction == "toRemote":
