    if status is not None and status != cur.get("status"):
        transitions = {
            "active": {"disabled", "deleted"},
            "disabled": {"active", "deleted"},
            "deleted": set(),
        }
        cur_status = cur.get("status")
        if cur_status not in transitions or status not in transitions[cur_status]:
            return _log_and_return(_err("INVALID_TRANSITION", f"Cannot transition credential status from {cur_status} to {status}.", from_status=cur_status, to_status=status), 409, wsid=wsid, err_code="INVALID_TRANSITION")

