    if sortBy not in ("createdAt", "startedAt", "finishedAt", "updatedAt", "status"):
        return _log_and_return(_err("VALIDATION_ERROR", "sortBy must be one of: createdAt, startedAt, finishedAt, updatedAt, status.", field="sortBy"), 400, err_code="VALIDATION_ERROR")
    if sortOrder not in ("asc", "desc"):
        return _log_and_return(_err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.", field="sortOrder"), 400, err_code="VALIDATION_ERROR")

    workspaces = _load("workspaces.json")
    execs = _load("ssh_command_executions.json")
    if not isinstance(workspaces, list):
        workspaces = []
    if not isinstance(execs, list):
        execs = []

    ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspaceId and w.get("status") != "deleted"), None)
    if not ws:
        # For list endpoints, missing workspace is treated as NOT_FOUND
        return _log_and_return(_err("NOT_FOUND", "Workspace not found."), 404, wsid=workspaceId, err_code="NOT_FOUND")

    # Filter
    rows = []
    for r in execs:
        if not isinstance(r, dict):
            continue
        if r.get("workspace_id") != workspaceId:
            continue
        if credentialId is not None and r.get("credential_id") != credentialId:
            continue
        if status is not None and r.get("status") != status:
            continue
        rows.append(r)

    # Sort
    sort_map = {
        "createdAt": "created_at",
        "startedAt": "started_at",
        "finishedAt": "finished_at",
        "updatedAt": "updated_at",
        "status": "status",
    }
    key_field = sort_map[sortBy]

    def _sort_key(x):
        v = x.get(key_field)
        # None values sort last for asc, first for desc (common API behavior); implement by tuple
        # Use string compare since timestamps are ISO.
        return (v is None, v if v is not None else "")

    reverse = (sortOrder == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor: accept opaque cursor; we interpret it as "start after id == cursor" or base64-encoded id.
    start = 0
    if cursor:
        cur = cursor
        # try base64 decode
        try:
            decoded = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            dec_s = decoded.decode("utf-8", errors="ignore").strip()
            if dec_s:
                cur = dec_s
        except Exception:
            pass
        for i, r in enumerate(rows):
            if r.get("id") == cur:
                start = i + 1
                break

    page = rows[start:start + limit]
    has_more = start + limit < len(rows)
    next_cursor = page[-1].get("id") if (has_more and page and isinstance(page[-1], dict)) else None

    resp = {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": bool(has_more),
            "next_cursor": next_cursor,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        }
    }
    return _log_and_return(resp, 200, wsid=workspaceId)

def list_rsync_transfers(workspaceId, credentialId=None, direction=None, status=None, limit=None, cursor=None, sortBy=None, sortOrder=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- validation ---
    if not isinstance(workspaceId, str) or not re.match(r"^ssh_ws_[0-9A-Z]{18,}$", workspaceId):
        return _err("VALIDATION_ERROR", "workspaceId is malformed.")
    if credentialId is not None:
        if not isinstance(credentialId, str) or not re.match(r"^ssh_cred_[0-9A-Z]{18,}$", credentialId):
            return _err("VALIDATION_ERROR", "credentialId is malformed.")
    if direction is not None and direction not in ("toRemote", "fromRemote"):
        return _err("VALIDATION_ERROR", "direction must be one of: toRemote, fromRemote.")
    if status is not None and status not in ("queued", "running", "succeeded", "failed", "cancelled"):
        return _err("VALIDATION_ERROR", "status must be one of: queued, running, succeeded, failed, cancelled.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.")
    if sortBy is None:
        sortBy = "createdAt"
    if sortBy not in ("createdAt", "startedAt", "finishedAt", "updatedAt", "status"):
        return _err("VALIDATION_ERROR", "sortBy must be one of: createdAt, startedAt, finishedAt, updatedAt, status.")
    if sortOrder is None:
        sortOrder = "desc"
    if sortOrder not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sortOrder must be one of: asc, desc.")

    # --- load store ---
    workspaces = _load("workspaces.json")
    rsync_transfers = _load("rsync_transfers.json")
    creds = _load("ssh_credentials.json")
    api_keys = _load("api_keys.json")  # used as ambient auth context selector (must find a usable combination)

    ws = next((w for w in workspaces if w.get("id") == workspaceId), None)
    if not ws or ws.get("status") == "deleted":
        # "cannot view audit logs" can also be interpreted as unauthorized; but malformed/missing workspace is NOT_FOUND
        return _err("NOT_FOUND", "Workspace not found.")
    if ws.get("status") != "active":
        return _err("UNAUTHORIZED", "Workspace is not active; cannot view audit logs.")

    # Ambient auth resolution: find any active api key for this workspace.
    # If none exist anywhere for this workspace, treat as unauthorized to view audit logs.
    usable_key = next((k for k in api_keys if k.get("workspace_id") == workspaceId and k.get("status") == "active"), None)
    if not usable_key:
        return _err("UNAUTHORIZED", "No active API key is authorized to view this workspace's audit logs.")

    # --- optional reference validation ---
    if credentialId is not None:
        c = next((r for r in creds if r.get("id") == credentialId), None)
        if not c or c.get("workspace_id") != workspaceId:
            return _err("NOT_FOUND", "credentialId not found in this workspace.")

    # --- cursor handling ---
    # Opaque cursor format: "v1:<offset>" where offset is integer >= 0.
    offset = 0
    if cursor:
        if not cursor.startswith("v1:"):
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        off_s = cursor[3:]
        if not off_s.isdigit():
            return _err("VALIDATION_ERROR", "cursor is malformed.")
        offset = int(off_s)

    # --- filtering ---
    rows = [r for r in rsync_transfers if r.get("workspace_id") == workspaceId]
    if credentialId is not None:
        rows = [r for r in rows if r.get("credential_id") == credentialId]
    if direction is not None:
        rows = [r for r in rows if r.get("direction") == direction]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    total = len(rows)

    # --- sorting ---
    key_map = {
        "createdAt": "created_at",
        "startedAt": "started_at",
        "finishedAt": "finished_at",
        "updatedAt": "updated_at",
        "status": "status",
    }
    sort_field = key_map[sortBy]

    def _sort_key(r):
        v = r.get(sort_field)
        # sort None consistently
        if v is None:
            return ("", "") if sort_field != "status" else ("", "")
        return (v, r.get("id", ""))

    reverse = (sortOrder == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except TypeError:
        # If mixed types exist due to bad historical data, fall back to string compare
        rows.sort(key=lambda r: (str(r.get(sort_field) or ""), r.get("id", "")), reverse=reverse)

    # --- paginate ---
    if offset > total:
        # offset beyond end is valid but returns empty
        page = []
    else:
        page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"v1:{next_offset}" if has_more else None

    # --- record audit/usage dynamics (best-effort, no schema file provided) ---
    # If a request log file exists, append; otherwise do nothing.
    latency_ms = int((time.time() - t0) * 1000)
    log_entry = {
        "id": f"req_{int(time.time()*1000)}",
        "endpoint": "list_rsync_transfers",
        "workspace_id": workspaceId,
        "api_key_id": usable_key.get("id"),
        "status": "succeeded",
        "http_status": 200,
        "timestamp": now,
        "latency_ms": latency_ms,
    }
    reqlog_name = "request_logs.json"
    if os.path.exists(os.path.join(_DB, reqlog_name)):
        reqlog = _load(reqlog_name)
        if isinstance(reqlog, list):
            reqlog.append(log_entry)
            _save(reqlog_name, reqlog)

    return {
        "transfers": page,
        "page": {
            "limit": limit,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "cursor": cursor,
            "sort_by": sortBy,
            "sort_order": sortOrder,
        },
    }

def cancel_job(jobType, jobId, reason=None, **_extra):
    import json, os, datetime, time, re, secrets, string

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0436000" if __import__("os").path.isdir("./environment_mix/0436000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix, rows):
        alphabet = string.ascii_uppercase + string.digits
        existing = {r.get("id") for r in rows if isinstance(r, dict)}
        for _ in range(200):
            suffix = "".join(secrets.choice(alphabet) for _ in range(22))
            _id = f"{prefix}{suffix}"
            if _id not in existing:
                return _id
        ts = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f")
        return f"{prefix}{ts}"

    reqlog_name = "request_logs.json"
    reqlogs = _load(reqlog_name)
    if not isinstance(reqlogs, list):
        reqlogs = []

    def _log_and_return(payload, http_status, wsid=None, keyid=None, err_code=None):
        reqlogs.append({
            "id": _gen_id("req_", reqlogs),
            "endpoint": "cancel_job",
            "timestamp": _now(),
            "status": http_status,
            "latency_ms": int(round((time.time() - t0) * 1000)),
            "workspace_id": wsid,
            "api_key_id": keyid,
            "error_code": err_code,
        })
        _save(reqlog_name, reqlogs)
        return payload

    if not isinstance(jobType, str) or jobType not in ("sshCommandExecution", "rsyncTransfer"):
        return _log_and_return(_err("VALIDATION_ERROR", "jobType must be one of: sshCommandExecution, rsyncTransfer.", field="jobType"), 400, err_code="VALIDATION_ERROR")
    if not isinstance(jobId, str) or not jobId.strip():
        return _log_and_return(_err("VALIDATION_ERROR", "jobId is missing or malformed.", field="jobId"), 400, err_code="VALIDATION_ERROR")
    jobId = jobId.strip()
    if reason is not None and not isinstance(reason, str):
        return _log_and_return(_err("VALIDATION_ERROR", "reason must be a string.", field="reason"), 400, err_code="VALIDATION_ERROR")
    if isinstance(reason, str):
        reason = reason.strip()
        if reason == "":
            reason = None

    # Ambient authorization: require at least one active workspace exists (manage permission implied)
    workspaces = _load("workspaces.json")
    if not isinstance(workspaces, list):
        workspaces = []
    any_active_ws = any(isinstance(w, dict) and w.get("status") == "active" for w in workspaces)
    if not any_active_ws:
        return _log_and_return(_err("UNAUTHORIZED", "No active workspace available for this operation."), 401, err_code="UNAUTHORIZED")

    if jobType == "sshCommandExecution":
        fname = "ssh_command_executions.json"
        terminal = {"succeeded", "failed", "cancelled"}
    else:
        fname = "rsync_transfers.json"
        terminal = {"succeeded", "failed", "cancelled"}

    rows = _load(fname)
    if not isinstance(rows, list):
        rows = []

    idx = None
    row = None
    for i, r in enumerate(rows):
        if isinstance(r, dict) and r.get("id") == jobId:
            idx = i
            row = r
            break

    if row is None:
        return _log_and_return(_err("NOT_FOUND", "Job not found."), 404, err_code="NOT_FOUND")

    wsid = row.get("workspace_id")
    cur_status = row.get("status")

    if cur_status in terminal:
        return _log_and_return(_err("CONFLICT", "Job is already in a terminal state and cannot be cancelled.", status=cur_status), 409, wsid=wsid, err_code="CONFLICT")

    # lifecycle: queued/running -> cancelled only
    allowed = {"queued": {"running", "cancelled", "failed"}, "running": {"succeeded", "failed", "cancelled"}}
    if cur_status not in allowed or "cancelled" not in allowed[cur_status]:
        return _log_and_return(_err("INVALID_TRANSITION", f"Cannot transition job status from {cur_status} to cancelled.", from_status=cur_status, to_status="cancelled"), 409, wsid=wsid, err_code="INVALID_TRANSITION")

    now = _now()
    # set started_at if it was running but missing started_at (repair)
    if cur_status == "running" and not row.get("started_at"):
        row["started_at"] = now

    row["status"] = "cancelled"
    row["finished_at"] = now
    row["updated_at"] = now

    # record reason into error_message (fits schema) if provided and no prior message
    if reason:
        prior = row.get("error_message")
        if isinstance(prior, str) and prior.strip():
            row["error_message"] = (prior.strip() + " | cancelled: " + reason)[:4096]
        else:
            row["error_message"] = ("cancelled: " + reason)[:4096]
    else:
        # keep any existing message; if absent, set a default
        if not (isinstance(row.get("error_message"), str) and row.get("error_message").strip()):
            row["error_message"] = "cancelled by user request"

    rows[idx] = row
    _save(fname, rows)
    key = "sshCommandExecution" if jobType == "sshCommandExecution" else "rsyncTransfer"
    return _log_and_return({key: row}, 200, wsid=wsid, err_code=None)
